"""exp.py: apply patches (name list) to a copy of /app/quayside, replay, compare dead letters with baseline."""
import importlib, json, shutil, sys, os
from pathlib import Path
sys.path.insert(0, '/app/tools')
import replay

PATCHES = {
    'key': ('dedupe.py', '''    field = "idem_key"
    idem = payload.get(field)
    if idem:
        return f"{job_type}:{idem}"
''', '''    field = "idem" if payload.get("v") == 3 else "idem_key" if payload.get("v") == 2 else None
    idem = payload.get(field) if field else None
    if idem:
        return f"{job_type}:{idem}"
'''),
    'hb': ('lease.py', 'cfg.visibility_ms // 3', 'job.visibility_ms // 3'),
    'thr': ('retry.py', '''    msg["failures"] += 1
    if msg["failures"] >= job.max_attempts:
        return ("dead", "attempts-exhausted")
    if outcome == "throttled":
        return ("retry", now + retry_after_ms)
''', '''    if outcome == "throttled":
        return ("retry", now + retry_after_ms)
    msg["failures"] += 1
    if msg["failures"] >= job.max_attempts:
        return ("dead", "attempts-exhausted")
'''),
    'extra': ('schema.py', '''    known = set(REQUIRED[job_type]) | {"v", "sent_at", "idem", "idem_key"}
    extra = sorted(set(payload) - known)
    if extra:
        return f"unknown field {extra[0]}"
''', ''),
}


def build(names, extra_patches=()):
    d = Path('/tmp/w/pkg_' + '_'.join(names or ['base']))
    if d.exists():
        shutil.rmtree(d)
    shutil.copytree('/app/quayside', d / 'quayside')
    for n in names:
        f, old, new = PATCHES[n]
        p = d / 'quayside' / f
        t = p.read_text()
        assert old in t, n
        p.write_text(t.replace(old, new))
    return d


def run(d):
    # fresh interpreter per run to avoid module caching
    import subprocess
    code = f"""
import sys, json
sys.path.insert(0, '/app/tools')
import replay
from pathlib import Path
pkg = replay.load_package(Path('{d}'))
w = replay.read_root(Path('/app'))
out = replay.play(w['items'], lambda at: pkg, w['configs'], w['env'])
res = {{k: v[0] for k, v in out['outcomes'].items()}}
json.dump({{'res': res, 'logged': w['logged'], 'seen': sorted(out['seen'])}}, open('{d}/res.json', 'w'))
"""
    subprocess.run([sys.executable, '-c', code], check=True)
    return json.load(open(f'{d}/res.json'))


if __name__ == '__main__':
    base = run(build([]))
    logged = base['logged']
    base_dead = {m for m, (w, t) in logged.items() if w.startswith('dead-letter') and base['res'].get(m, 'pending').startswith('dead-letter')}
    print('logged dead', sum(1 for w, t in logged.values() if w.startswith('dead-letter')), 'base dead', len(base_dead))
    names = sys.argv[1:]
    sets = [[n] for n in names] if names else []
    for s in sets + ([names] if len(names) > 1 else []):
        r = run(build(s))
        fixed = [m for m in base_dead if not r['res'].get(m, 'pending').startswith('dead-letter')]
        fixed.sort(key=lambda m: logged[m][1])
        print(s, len(fixed), fixed[:1])
        # remaining
        rem = {}
        for m in base_dead:
            if r['res'].get(m, 'pending').startswith('dead-letter'):
                rem[logged[m][0]] = rem.get(logged[m][0], 0) + 1
        print('  remaining', rem)

